import { initTRPC, TRPCError } from '@trpc/server';
import { observable } from '@trpc/server/observable';
import { z } from 'zod';
import { physicalSecurityBus } from '../events/securityBus';
import type { WsContext } from '../types';

const t = initTRPC.context<WsContext>().create();

export const facilityRouter = t.router({
  onDoorBadgeEvent: t.procedure
    .input(z.object({ facilityId: z.string(), zoneId: z.string().optional() }))
    .subscription(async ({ input, ctx }) => {
      if (!ctx.auth?.userId) {
        throw new TRPCError({ code: 'UNAUTHORIZED' });
      }

      // Verify that user is authorized as a security operator for this facility
      const clearance = await ctx.db.facilityClearance.findFirst({
        where: {
          facilityId: input.facilityId,
          userId: ctx.auth.userId,
          role: { in: ['SECURITY_ADMIN', 'SECURITY_OFFICER'] }
        }
      });

      if (!clearance) {
        throw new TRPCError({
          code: 'FORBIDDEN',
          message: 'Access denied: insufficient security clearance for facility event monitoring'
        });
      }

      return observable<BadgeSwipeEvent>((emit) => {
        const listener = (event: BadgeSwipeEvent) => {
          if (event.facilityId === input.facilityId) {
            if (!input.zoneId || event.zoneId === input.zoneId) {
              emit.next(event);
            }
          }
        };

        physicalSecurityBus.on('badge_swipe', listener);
        return () => {
          physicalSecurityBus.off('badge_swipe', listener);
        };
      });
    }),
});
